@dataclass(frozen=True, init=False)
class Pattern:
    """One row of the scorecard: a kind of series, in plain words.

    ``predictable`` says what a perfect forecaster could get right;
    ``unpredictable`` what no forecaster can, by design.

    The row's series come from one of two functions. ``simulate(rng,
    history_length, horizon, noise)`` draws one series and returns a dict:
    ``values`` for all ``history_length + horizon`` steps (one column per series
    when there are several), and the ``mean`` and ``variance`` of each step to
    forecast, given the history. An optional ``covariance`` is for future steps
    that move together; without it they count as independent. ``rng`` is a
    NumPy random generator seeded by the scorecard and ``noise`` the column's
    standard deviation, which a pattern may use or ignore. TimeGym builds the
    case and its answer key from these. ``build(noise, history_length,
    horizon)`` instead returns a whole Scenario for one noise level, as the
    built-in rows do: the noise is the standard deviation of the random error
    on each observation. TimeGym passes these arguments by position, so your
    function may name them as it likes.

    ``attainable_by`` is a model of the generator's own family with every
    numeric parameter unknown, with ``fit(history)`` and ``predict(future_index)``:
    a model object, copied fresh for each series, or a class or function that
    returns a fresh one. Its score on the row is the row's attainable score; a
    pattern without one (``None``) has none. ``fitted`` is its old name and still
    works, with a warning.

    You can make your own Pattern and pass it to ``scenario_grid`` or
    ``Pipeline.scorecard`` beside the keys of ``PATTERNS``: a kind of series you
    can simulate, with its own answer key.
    """

    key: str
    title: str
    aka: str
    predictable: str
    unpredictable: str
    build: Callable[[float, int, int], Scenario] | None = field(
        default=None, repr=False, compare=False
    )
    attainable_by: object = field(default=None, repr=False, compare=False)
    simulate: Callable | None = field(default=None, repr=False, compare=False)

    def __init__(
        self,
        key,
        title,
        aka,
        predictable,
        unpredictable,
        build=None,
        attainable_by=None,
        *,
        simulate=None,
        fitted=None,
    ):
        if fitted is not None:
            warnings.warn(
                "Pattern(fitted=...) is now Pattern(attainable_by=...), which also takes the model itself; "
                "fitted will be removed in a later release",
                DeprecationWarning,
                stacklevel=2,
            )
            if attainable_by is not None:
                raise TypeError("give attainable_by, or its old name fitted, not both")
            attainable_by = fitted
        for name, value in (
            ("key", key),
            ("title", title),
            ("aka", aka),
            ("predictable", predictable),
            ("unpredictable", unpredictable),
            ("build", build),
            ("attainable_by", attainable_by),
            ("simulate", simulate),
        ):
            object.__setattr__(self, name, value)

    @property
    def fitted(self):
        """The old name of ``attainable_by``: a function that returns a fresh model, or None."""
        warnings.warn(
            "Pattern.fitted is now Pattern.attainable_by; fitted will be removed in a later release",
            DeprecationWarning,
            stacklevel=2,
        )
        if self.attainable_by is None:
            return None
        return lambda: _fresh_from(self.attainable_by)

    def __reduce__(self):
        # A built-in row pickles by its key, so a run that holds its scorecard pickles too; the
        # rows' build functions are lambdas. Your own pattern pickles if its functions do.
        if PATTERNS.get(self.key) is self:
            return (_built_in_pattern, (self.key,))
        return (
            _pattern_from_fields,
            (
                self.key,
                self.title,
                self.aka,
                self.predictable,
                self.unpredictable,
                self.build,
                self.attainable_by,
                self.simulate,
            ),
        )


def _built_in_pattern(key):
    """One of ``PATTERNS`` by its key: what a pickled built-in row reads back as."""
    return PATTERNS[key]


def _pattern_from_fields(
    key, title, aka, predictable, unpredictable, build, attainable_by, simulate
):
    """A pattern of your own read back from a pickle."""
    return Pattern(
        key,
        title,
        aka,
        predictable,
        unpredictable,
        build,
        attainable_by,
        simulate=simulate,
    )


class _Simulated:
    """What a pattern's ``simulate`` becomes for the grid: generate(seed) draws one series and builds its case."""

    def __init__(self, pattern, noise, history_length, horizon):
        self.pattern, self.noise = pattern, float(noise)
        self.kind, self.history_length, self.horizon = (
            pattern.key,
            history_length,
            horizon,
        )

    def generate(self, seed):
        """Call ``simulate`` with a generator seeded by ``seed``; cut the history from the future; build the answer key."""
        where = f"pattern {self.kind!r}: simulate"
        length, horizon = self.history_length, self.horizon
        parts = self.pattern.simulate(
            np.random.default_rng(seed), length, horizon, self.noise
        )
        if not isinstance(parts, Mapping):
            raise TypeError(
                f"{where} must return a dict with values, mean and variance; got a {type(parts).__name__}"
            )
        missing = [name for name in ("values", "mean", "variance") if name not in parts]
        unknown = sorted(
            str(name)
            for name in set(parts) - {"values", "mean", "variance", "covariance"}
        )
        if missing or unknown:
            problems = ([f"no {', '.join(missing)}"] if missing else []) + (
                [f"unknown {', '.join(unknown)}"] if unknown else []
            )
            raise ValueError(
                f"{where} must return values, mean and variance (and optionally covariance); "
                f"got {'; '.join(problems)}"
            )
        values = np.asarray(parts["values"], dtype=float)
        if values.ndim == 1:
            values = values[:, None]
        if values.ndim != 2 or len(values) != length + horizon or values.shape[1] == 0:
            raise ValueError(
                f"{where}: values must have {length + horizon} steps ({length} of history and {horizon} "
                f"to forecast), one column per series; got shape {np.shape(parts['values'])}"
            )
        shape = (horizon, values.shape[1])
        moments = {}
        for name in ("mean", "variance"):
            array = np.asarray(parts[name], dtype=float)
            if array.ndim == 1 and shape[1] == 1:
                array = array[:, None]
            if array.shape != shape:
                raise ValueError(
                    f"{where}: {name} must have one value per step to forecast"
                    f"{' and series' if shape[1] > 1 else ''}, shape {shape}; got {np.shape(parts[name])}"
                )
            moments[name] = array
        covariance = parts.get("covariance")
        covariance = (
            np.diag(moments["variance"].ravel())
            if covariance is None
            else np.asarray(covariance, dtype=float)
        )
        names = ("y",) if shape[1] == 1 else tuple(f"y{i}" for i in range(shape[1]))
        future = pd.RangeIndex(length, length + horizon)
        try:
            answer_key = Reference(
                mean=moments["mean"],
                variance=moments["variance"],
                covariance=covariance,
                index=future.copy(),
                target_names=names,
            )
        except ValueError as error:
            raise ValueError(f"{where}: {error}") from None
        history = pd.DataFrame(
            values[:length], index=pd.RangeIndex(length), columns=names
        )
        observed = pd.DataFrame(values[length:], index=future, columns=names)
        manifest = {
            "kind": self.kind,
            "seed": seed,
            "history_length": length,
            "horizon": horizon,
            "noise": self.noise,
        }
        return Case(ForecastTask(history, future), observed, answer_key, manifest)


def _cycle_coefficients(period=16.0, damping=0.95):
    """AR(2) weights whose shocks ring at ``period`` steps and fade by ``damping`` per step."""
    return 2 * damping * np.cos(2 * np.pi / period), -(damping**2)


_PHI1, _PHI2 = _cycle_coefficients()
_SEASON = 12.0  # steps in one seasonal cycle


